//! Actions-only pure import/persistence tests. Certificates are generated by
//! the Actions fixture; no network, SDK, device or registration execution.
use super::*;
use super::super::{tests::imported, tls_engine::tests::Certificates};

fn secret(json: &str) -> Secret { serde_json::from_str(json).unwrap() }
fn fixture(root: &str) -> AccountConfig {
    let mut credentials = imported();
    // Replace the legacy text fixtures with a real Actions-generated DER root
    // and the exact supported reference/selector, not guessed trust bytes.
    credentials.sdk.root_der_base64 = Secret::deserialize(serde::de::value::StrDeserializer::<serde::de::value::Error>::new(root)).unwrap();
    credentials.sdk.server_address = secret("\"#fixture-account:tcp -h fixture.invalid -p 443;\"");
    credentials.sdk.selected_session_id = Some(secret("\"fixture-original-selector\""));
    credentials.sdk.client_config_decode_key = Some(secret("\"fixture-client-context\""));
    credentials.sdk.reference_decode_key = Some(secret("\"fixture-reference-context\""));
    AccountConfig { credentials, profile: ProfileConfig {
        route: ProfileRoute::DirectTlsCarrier, authority: secret("\"fixture.invalid\""), enable_sni: true,
        identity_type: secret("\"username\""), domain_name: secret("\"fixture.invalid\""),
        domain_id: secret("\"fixture-domain\""), application_id: secret("\"fixture-app\""),
        device_info_cc: secret("\"fixture-cc\""), include_device_id: true,
        client_properties: vec![ProfileProperty { key: b"ClientId".to_vec(), value: b"fixture-exact-client-id".to_vec() },
            ProfileProperty { key: vec![0, 0xff, 1], value: vec![0xff, 0, 2] }],
        login_routing: vec![ProfileProperty { key: vec![0xfe], value: vec![0, 0xff] }],
        gateway_uri: secret("\"fixture-exact-gateway-uri\""),
        gateway_metadata: vec![ProfileProperty { key: b"id".to_vec(), value: b"#fixture-gateway".to_vec() },
            ProfileProperty { key: b"domain".to_vec(), value: b"fixture-domain".to_vec() }],
        poll_routing: vec![ProfileProperty { key: vec![0xfd], value: vec![0xff, 0] }],
        logout_routing: vec![ProfileProperty { key: vec![0xfc], value: vec![0, 0xff] }],
        incoming: Some(IncomingBinding { object_id: b"#fixture-client".to_vec(), domain: b"fixture-domain".to_vec(),
            receiver_kind: b"fixture.kind".to_vec() }),
        connect_timeout_ms: 1000, handshake_timeout_ms: 3000, partial_timeout_ms: 300,
        io_timeout_ms: 2000, rpc_timeout_ms: 2000,
    } }
}
fn public_json(config: &AccountConfig) -> Zeroizing<String> {
    let mut bytes = Zeroizing::new(Vec::with_capacity(MAX_PRIVATE_BYTES));
    serde_json::to_writer(PrivateWriter(&mut bytes), &PrivateConfigRef::new(config)).unwrap();
    Zeroizing::new(std::str::from_utf8(&bytes).unwrap().to_owned())
}
fn replaced(input: &str, from: &str, to: &str) -> Zeroizing<String> {
    assert!(input.contains(from));
    Zeroizing::new(input.replacen(from, to, 1))
}

#[test]
fn private_roundtrip_preserves_binary_properties_and_every_optional_field() {
    let cert = Certificates::generate("DNS:fixture.invalid");
    let mut config = fixture(&cert.root);
    assert_eq!(config.validate(100), Ok(()));
    assert!(config.runtime_profile().is_ok());
    for expiry in [None, Some(200), Some(u64::MAX)] {
        config.credentials.sdk.expires_at_unix_seconds = expiry;
        let bytes = config.encode_private().unwrap();
        let loaded = AccountConfig::decode_private(&bytes).unwrap();
        assert_eq!(bytes.as_slice(), loaded.encode_private().unwrap().as_slice());
        assert_eq!(loaded.profile.client_properties[1].key, [0, 0xff, 1]);
        assert_eq!(loaded.profile.client_properties[1].value, [0xff, 0, 2]);
        assert_eq!(loaded.credentials.sdk.expires_at_unix_seconds, expiry);
        assert_eq!(loaded.credentials.hosting.delete_int_code, "fixture-policy");
        assert_eq!(exposed(&loaded.credentials.sdk.client_config_decode_key), Some("fixture-client-context"));
        assert_eq!(exposed(&loaded.credentials.sdk.reference_decode_key), Some("fixture-reference-context"));
    }
    config.credentials.sdk.device_id = None;
    config.credentials.sdk.selected_session_id = None;
    config.credentials.sdk.client_config_decode_key = None;
    config.credentials.sdk.reference_decode_key = None;
    config.profile.incoming = None;
    let bytes = config.encode_private().unwrap();
    let loaded = AccountConfig::decode_private(&bytes).unwrap();
    assert_eq!(bytes.as_slice(), loaded.encode_private().unwrap().as_slice());
    assert!(loaded.credentials.sdk.device_id.is_none());
    assert!(loaded.credentials.sdk.selected_session_id.is_none());
    assert!(loaded.credentials.sdk.client_config_decode_key.is_none());
    assert!(loaded.credentials.sdk.reference_decode_key.is_none());
    assert!(loaded.profile.incoming.is_none());
}

#[test]
fn public_import_denies_unknown_fields_wrong_route_and_implicit_timeouts() {
    let cert = Certificates::generate("DNS:fixture.invalid");
    let config = fixture(&cert.root);
    let json = public_json(&config);
    for (from, to) in [
        ("\"credentials\":", "\"unknown\":true,\"credentials\":"),
        ("\"sdk\":{", "\"sdk\":{\"unknown\":true,"),
        ("\"hosting\":{", "\"hosting\":{\"unknown\":true,"),
        ("\"profile\":{", "\"profile\":{\"reference_decode_key\":\"not-allowed\","),
        ("\"key\":[", "\"unknown\":true,\"key\":["),
        ("\"object_id\":[", "\"unknown\":true,\"object_id\":["),
        ("\"direct_tls_carrier\"", "\"direct_tcp\""),
        ("\"direct_tls_carrier\"", "null"),
        ("\"connect_timeout_ms\":1000,", ""),
        ("\"handshake_timeout_ms\":3000,", ""),
        ("\"partial_timeout_ms\":300,", ""),
        ("\"io_timeout_ms\":2000,", ""),
        (",\"rpc_timeout_ms\":2000", ""),
    ] {
        let invalid = replaced(&json, from, to);
        assert!(serde_json::from_str::<AccountConfig>(&invalid).is_err());
    }
}

#[test]
fn private_import_denies_unknown_version_missing_fields_and_malformed_or_oversize_json() {
    let cert = Certificates::generate("DNS:fixture.invalid");
    let config = fixture(&cert.root);
    let bytes = config.encode_private().unwrap();
    let json = std::str::from_utf8(&bytes).unwrap();
    for (from, to) in [
        ("\"format_version\":1", "\"format_version\":2"),
        ("\"format_version\":1", "\"format_version\":0"),
        ("\"format_version\":1,", ""),
        ("\"format_version\":1", "\"unknown\":1,\"format_version\":1"),
        ("\"format_version\":1", "\"format_version\":1,\"format_version\":1"),
        ("\"config\":", "\"config\":null,\"extra\":"),
    ] {
        let invalid = replaced(json, from, to);
        assert_eq!(AccountConfig::decode_private(invalid.as_bytes()).err(), Some(INVALID));
    }
    for invalid in [b"".as_slice(), b"{", b"null", b"[]", b"{\"format_version\":1}", b"{} {}"] {
        assert_eq!(AccountConfig::decode_private(invalid).err(), Some(INVALID));
    }
    assert_eq!(AccountConfig::decode_private(&vec![b' '; MAX_PRIVATE_BYTES + 1]).err(), Some(INVALID));
    let mut huge = config.clone();
    huge.profile.client_properties[1].value = vec![0xff; MAX_PRIVATE_BYTES];
    assert_eq!(huge.encode_private().err(), Some(INVALID));
}

#[test]
fn all_timeout_boundaries_are_explicit_and_enforced() {
    let cert = Certificates::generate("DNS:fixture.invalid");
    let fixture = fixture(&cert.root);
    for (index, max) in [(0, 10_000), (1, 30_000), (2, 30_000), (3, 30_000), (4, 60_000)] {
        for value in [0, 1, max, max + 1, u64::MAX] {
            let mut config = fixture.clone();
            let p = &mut config.profile;
            let timeouts = [&mut p.connect_timeout_ms, &mut p.handshake_timeout_ms, &mut p.partial_timeout_ms,
                &mut p.io_timeout_ms, &mut p.rpc_timeout_ms];
            *timeouts.into_iter().nth(index).unwrap() = value;
            assert_eq!(config.validate(100).is_ok(), value >= 1 && value <= max);
            assert_eq!(config.runtime_profile().is_ok(), value >= 1 && value <= max);
        }
    }
}

#[test]
fn credentials_selector_identity_device_profile_root_and_reference_fail_before_io() {
    let cert = Certificates::generate("DNS:fixture.invalid");
    let good = fixture(&cert.root);
    assert_eq!(good.validate(100), Ok(()));
    assert_eq!(good.validate(200), Err(INVALID));
    for value in ["\"\"", "\"   \"", "\"ENC(fake)\""] {
        let mut config = good.clone();
        config.credentials.sdk.phone_login_token = secret(value);
        assert_eq!(config.validate(100), Err(INVALID));
    }
    let mut config = good.clone();
    config.credentials.sdk.selected_session_id = None;
    assert_eq!(config.validate(100), Err(INVALID));
    for value in ["\"\"", "\"   \"", "\"ENC(fake)\""] {
        let mut config = good.clone();
        config.credentials.sdk.selected_session_id = Some(secret(value));
        assert_eq!(config.validate(100), Err(INVALID));
    }
    for identity in ["\"a:b\"", "\"[a\"", "\"a]\"", "\"a@b\""] {
        let mut config = good.clone();
        config.credentials.sdk.account_identity = secret(identity);
        assert_eq!(config.validate(100), Err(INVALID));
    }
    let mut config = good.clone();
    config.profile.include_device_id = false;
    assert_eq!(config.validate(100), Err(INVALID));
    config.credentials.sdk.device_id = None;
    assert_eq!(config.validate(100), Ok(()));
    for root in ["\"\"", "\"not-base64\"", "\"AA==\""] {
        let mut config = good.clone();
        config.credentials.sdk.root_der_base64 = secret(root);
        assert_eq!(config.validate(100), Err(INVALID));
    }
    for reference in ["\"fixture.invalid\"", "\"#fixture-account:tcp -h other.invalid -p 443;\"",
        "\"#fixture-account:tls -h fixture.invalid -p 443;\"", "\"ENC(invalid)\""] {
        let mut config = good.clone();
        config.credentials.sdk.server_address = secret(reference);
        assert_eq!(config.validate(100), Err(INVALID));
    }
    let mut config = good.clone();
    config.credentials.sdk.server_address = secret("\"ENC(invalid)\"");
    config.credentials.sdk.reference_decode_key = None;
    // A Client key must NEVER be used as a substitute reference context.
    assert!(config.credentials.sdk.client_config_decode_key.is_some());
    assert_eq!(config.validate(100), Err(INVALID));
    let mut config = good.clone();
    config.profile.client_properties.clear();
    assert_eq!(config.validate(100), Err(INVALID));
    let mut config = good.clone();
    config.profile.client_properties.push(config.profile.client_properties[0].clone());
    assert_eq!(config.validate(100), Err(INVALID));
    let mut config = good.clone();
    config.profile.login_routing.push(ProfileProperty { key: b"pwd".to_vec(), value: b"not-imported".to_vec() });
    assert_eq!(config.validate(100), Err(INVALID));
    let mut config = good.clone();
    config.profile.incoming.as_mut().unwrap().receiver_kind.push(b'*');
    assert_eq!(config.validate(100), Err(INVALID));
}

#[test]
fn reference_envelope_uses_only_the_supplied_reference_context() {
    let cert = Certificates::generate("DNS:fixture.invalid");
    let mut config = fixture(&cert.root);
    let envelope = Zeroizing::new(super::super::legacy_config::tests::fixture_envelope(
        b"#fixture-account:tcp -h fixture.invalid -p 443;",
        b"fixture-reference-context", [8, 7, 6, 5, 4, 3, 2, 1],
    ));
    config.credentials.sdk.server_address = Secret::deserialize(
        serde::de::value::StrDeserializer::<serde::de::value::Error>::new(std::str::from_utf8(&envelope).unwrap())
    ).unwrap();
    assert_eq!(config.validate(100), Ok(()));
    let private = config.encode_private().unwrap();
    assert_eq!(AccountConfig::decode_private(&private).unwrap().validate(100), Ok(()));
    config.credentials.sdk.reference_decode_key = None;
    assert!(config.credentials.sdk.client_config_decode_key.is_some());
    assert_eq!(config.validate(100), Err(INVALID));
    config.credentials.sdk.reference_decode_key = Some(secret("\"fixture-client-context\""));
    assert_eq!(config.validate(100), Err(INVALID));
}

#[test]
fn profile_map_field_and_private_writer_bounds_fail_without_partial_success() {
    let cert = Certificates::generate("DNS:fixture.invalid");
    let mut config = fixture(&cert.root);
    config.profile.client_properties[1].value = vec![0xff; MAX_FIELD_BYTES + 1];
    assert_eq!(config.runtime_profile().err(), Some(INVALID));
    let mut config = fixture(&cert.root);
    config.profile.login_routing = (0..=MAX_MAP_ENTRIES).map(|n| ProfileProperty {
        key: n.to_be_bytes().to_vec(), value: vec![0xff, 0],
    }).collect();
    assert_eq!(config.runtime_profile().err(), Some(INVALID));
    let mut config = fixture(&cert.root);
    config.profile.domain_name = secret("\"   \"");
    assert_eq!(config.validate(100), Err(INVALID));
    let mut bytes = Zeroizing::new(Vec::with_capacity(MAX_PRIVATE_BYTES));
    let mut writer = PrivateWriter(&mut bytes);
    assert_eq!(io::Write::write(&mut writer, &vec![b' '; MAX_PRIVATE_BYTES]).unwrap(), MAX_PRIVATE_BYTES);
    assert!(io::Write::write(&mut writer, &[b'x']).is_err());
    assert_eq!(bytes.len(), MAX_PRIVATE_BYTES);
}

#[test]
fn debugging_is_fully_redacted_without_secret_values_lengths_or_policy() {
    let cert = Certificates::generate("DNS:fixture.invalid");
    let config = fixture(&cert.root);
    assert_eq!(format!("{config:?}"), "AccountConfig(<redacted>)");
    assert_eq!(format!("{:?}", config.profile), "ProfileConfig(<redacted>)");
    assert_eq!(format!("{:?}", config.profile.client_properties[0]), "ProfileProperty(<redacted>)");
    assert_eq!(format!("{:?}", config.profile.incoming.as_ref().unwrap()), "IncomingBinding(<redacted>)");
    assert_eq!(format!("{:?}", config.runtime_profile().unwrap()), "RuntimeProfile(<redacted>)");
}
